segments=[]
for slot,base_id in ((48,1),(49,14)):
    e,data=entry(slot); p=0; ordinal=0
    while p<len(data):
        q=data.find(b'overlay',p)
        if q<0: raise ValueError((slot,p,'missing final overlay marker'))
        module_id=base_id+ordinal
        segments.append({'slot':slot,'module_id':module_id,'name':f'Overlay{module_id:02d}','offset':p,'length':q+7-p,'code_payload_length':q-p,'runtime_origin':0xB200,'entrypoints':[0xB200],'trailer':'overlay','logical_bank':12 if slot==48 else 13,'code_data_status':'contains code and inline data; recursive CFG required'})
        add(slot,p+0xC000,f'Overlay{module_id:02d}','начало модуля, исполняемого после переноса в #B200',f'номер{module_id}, смещение в файле #{p:04X}, длина{q+7-p}, конечный маркер overlay входит в копирование')
        p=q+7;ordinal+=1

