    segment['purpose']=purpose
    k=f"{segment['slot']}:{segment['offset']+0xC000:04X}"
    annotations[k]['purpose']=purpose
    annotations[k]['details']+='; назначение подтверждается строками интерфейса модуля и таблицей клавиш #653A'
    annotations[k]['confidence']='proven' if module not in (6,11,12,18,19) else 'strong'

